# reproduce boxes / selected centers
h,w=len(di),len(di[0]); seen=set(); boxes=[]
for r in range(h):
 for c in range(w):
  if di[r][c]!=3 or (r,c) in seen: continue
  st=[(r,c)]; seen.add((r,c)); cells=[]
  while st:
   y,x=st.pop(); cells.append((y,x))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    q=(y+dy,x+dx)
    if 0<=q[0]<h and 0<=q[1]<w and di[q[0]][q[1]]==3 and q not in seen: seen.add(q);st.append(q)
  boxes.append((min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells)))
centers=[(r,c) for r in range(h) for c in range(w) if di[r][c]==2 and any(r0<=r<=r1 and c0<=c<=c1 for r0,r1,c0,c1 in boxes)]
print(boxes,centers)
print('\n'.join(' '.join(map(str,row)) for row in di))
